mapper.select:
select owr.id, owr.wholesale_return_no, owr.return_status, owr.client_code, owr.price_group_code, owr.storage_wrh, owr.storage_stock_code, owr.is_reversal, owr.is_reversal_order,
owr.application_quantity, owr.application_amount,owr.storage_quantity, owr.storage_amount, owr.tracking_no, owr.source_no, owr.wholesale_shipment_no,
owr.returns_reason, owr.org_code, owr.consignee, owr.distribution_info_id, owr.consignee_phone, owr.address_detail,
owr.biz_org_code, owr.remark, owr.creator, owr.create_time, owr.updater, owr.update_time, owr.is_delete, lsi.stock_name storageStockCodeStr,
lwi.warehouse_name storageWrhStr, owr.receive_time,owr.audit_time
from ord_wholesale_returns owr
LEFT JOIN logc_stock_info lsi ON lsi.stock_code = owr.storage_stock_code AND lsi.is_delete = 0 and lsi.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode}
LEFT JOIN logc_warehouse_info lwi ON lwi.warehouse_code = owr.storage_wrh AND lwi.id = lsi.warehouse_id AND lwi.is_delete = 0 and lwi.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode}

    INNER JOIN ord_wholesale_return_detail rd on rd.wholesale_return_id = owr.id



        and owr.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode,jdbcType=VARCHAR}


        and  owr.wholesale_return_no = #{wholesaleReturnsListIn.wholesaleReturnNo,jdbcType=VARCHAR}


        and owr.return_status = #{wholesaleReturnsListIn.returnStatus,jdbcType=VARCHAR}


        and owr.client_code = #{wholesaleReturnsListIn.clientCode,jdbcType=VARCHAR}


        and owr.storage_wrh = #{wholesaleReturnsListIn.storageWrh,jdbcType=VARCHAR}


        and owr.storage_stock_code = #{wholesaleReturnsListIn.storageStockCode,jdbcType=VARCHAR}


        and owr.tracking_no = #{wholesaleReturnsListIn.trackingNo}


        and owr.source_no = #{wholesaleReturnsListIn.sourceNo}


        and owr.is_reversal = #{wholesaleReturnsListIn.isReversal,jdbcType=INTEGER}


        and owr.is_reversal_order = #{wholesaleReturnsListIn.isReversalOrder,jdbcType=INTEGER}


        and owr.create_time >= #{wholesaleReturnsListIn.startCreateTime,jdbcType=TIMESTAMP}


        and owr.create_time <= #{wholesaleReturnsListIn.endCreateTime,jdbcType=TIMESTAMP}


        and owr.receive_time >= #{wholesaleReturnsListIn.receiveTimeBegin}


        and owr.receive_time <= #{wholesaleReturnsListIn.receiveTimeEnd}


        and owr.is_delete = #{wholesaleReturnsListIn.isDelete,jdbcType=INTEGER}


        and owr.creator like CONCAT('%',#{wholesaleReturnsListIn.creator},'%')


        and rd.goods_code = #{wholesaleReturnsListIn.goodsCode}


order by owr.create_time desc,owr.id desc

select owr.id
from ord_wholesale_returns owr
LEFT JOIN logc_stock_info lsi ON lsi.stock_code = owr.storage_stock_code AND lsi.is_delete = 0 and lsi.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode}
LEFT JOIN logc_warehouse_info lwi ON lwi.warehouse_code = owr.storage_wrh AND lwi.id = lsi.warehouse_id AND lwi.is_delete = 0 and lwi.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode}

    INNER JOIN ord_wholesale_return_detail rd on rd.wholesale_return_id = owr.id



        and owr.biz_org_code = #{wholesaleReturnsListIn.bizOrgCode,jdbcType=VARCHAR}


        and  owr.wholesale_return_no = #{wholesaleReturnsListIn.wholesaleReturnNo,jdbcType=VARCHAR}


        and owr.return_status = #{wholesaleReturnsListIn.returnStatus,jdbcType=VARCHAR}


        and owr.client_code = #{wholesaleReturnsListIn.clientCode,jdbcType=VARCHAR}


        and owr.storage_wrh = #{wholesaleReturnsListIn.storageWrh,jdbcType=VARCHAR}


        and owr.storage_stock_code = #{wholesaleReturnsListIn.storageStockCode,jdbcType=VARCHAR}


        and owr.tracking_no = #{wholesaleReturnsListIn.trackingNo}


        and owr.source_no = #{wholesaleReturnsListIn.sourceNo}


        and owr.is_reversal = #{wholesaleReturnsListIn.isReversal,jdbcType=INTEGER}


        and owr.is_reversal_order = #{wholesaleReturnsListIn.isReversalOrder,jdbcType=INTEGER}


        and owr.create_time >= #{wholesaleReturnsListIn.startCreateTime,jdbcType=TIMESTAMP}


        and owr.create_time <= #{wholesaleReturnsListIn.endCreateTime,jdbcType=TIMESTAMP}


        and owr.receive_time >= #{wholesaleReturnsListIn.receiveTimeBegin}


        and owr.receive_time <= #{wholesaleReturnsListIn.receiveTimeEnd}


        and owr.is_delete = #{wholesaleReturnsListIn.isDelete,jdbcType=INTEGER}


        and owr.creator like CONCAT('%',#{wholesaleReturnsListIn.creator},'%')


        and rd.goods_code = #{wholesaleReturnsListIn.goodsCode}


order by owr.create_time desc,owr.id desc
